INSERT INTO rol_permiso (rol_id, permiso_id) SELECT r.id, p.id FROM rol r CROSS JOIN permiso p WHERE r.clave = 'administrador';
INSERT INTO rol_permiso (rol_id, permiso_id) SELECT r.id, p.id FROM rol r JOIN permiso p ON p.clave IN ('pedidos.ver', 'pedidos.cambiar_estado', 'inventario.ver', 'inventario.movimiento', 'entregas.ver', 'entregas.asignar', 'entregas.cerrar', 'indicadores.ver', 'productos.ver', 'catalogo_publico.ver') WHERE r.clave = 'operador';
INSERT INTO rol_permiso (rol_id, permiso_id) SELECT r.id, p.id FROM rol r JOIN permiso p ON p.clave IN ('pedidos.ver', 'pedidos.reasignar', 'indicadores.ver', 'simulacion.ver', 'simulacion.ejecutar', 'zonas.ver', 'microhubs.ver', 'productos.ver', 'catalogo_publico.ver') WHERE r.clave = 'planeador';
INSERT INTO rol_permiso (rol_id, permiso_id) SELECT r.id, p.id FROM rol r JOIN permiso p ON p.clave IN ('pedidos.ver', 'pedidos.crear', 'pedidos.cancelar', 'catalogo_publico.ver', 'productos.ver') WHERE r.clave = 'cliente';
INSERT INTO rol_permiso (rol_id, permiso_id) SELECT r.id, p.id FROM rol r JOIN permiso p ON p.clave IN ('entregas.ver', 'entregas.cerrar', 'pedidos.ver') WHERE r.clave = 'repartidor';
INSERT INTO rol_permiso (rol_id, permiso_id) SELECT r.id, p.id FROM rol r JOIN permiso p ON p.clave IN ('bitacora.ver', 'pedidos.ver', 'inventario.ver', 'entregas.ver', 'indicadores.ver', 'usuarios.ver', 'configuracion.ver') WHERE r.clave = 'auditor';
INSERT INTO rol_permiso (rol_id, permiso_id) SELECT r.id, p.id FROM rol r JOIN permiso p ON p.clave IN ('catalogo_publico.ver') WHERE r.clave = 'visitante';
